/* DAWAH X — darimi, অধ্যায় 10 · খণ্ড 10 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][10]=[[1801,1801,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ الْمَاجِشُونِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مِنًى ‏ ‏فَمِنَّا مَنْ يُكَبِّرُ وَمِنَّا مَنْ يُلَبِّي ‏","","",""],[1802,1802,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الثَّقَفِيُّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏وَنَحْنُ ‏ ‏غَادِيَانِ ‏ ‏مِنْ ‏ ‏مِنًى ‏ ‏إِلَى ‏ ‏عَرَفَاتٍ ‏ ‏عَنْ التَّلْبِيَةِ كَيْفَ كُنْتُمْ تَصْنَعُونَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏يُلَبِّي الْمُلَبِّي فَلَا يُنْكَرُ عَلَيْهِ وَيُكَبِّرُ الْمُكَبِّرُ فَلَا يُنْكَرُ عَلَيْهِ ‏","","",""],[1803,1803,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ قَالَ ‏ ‏جُبَيْرٌ ‏ ‏أَضْلَلْتُ بَعِيرًا لِي فَذَهَبْتُ أَطْلُبُهُ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفًا مَعَ النَّاسِ ‏ ‏بِعَرَفَةَ ‏ ‏فَقُلْتُ وَاللَّهِ إِنَّ هَذَا لَمِنْ ‏ ‏الْحُمْسِ ‏ ‏فَمَا شَأْنُهُ هَا هُنَا ‏","","",""],[1804,1804,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَى ثُمَّ قَعَدَ لِلنَّاسِ فَجَاءَهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي حَلَقْتُ قَبْلَ أَنْ أَنْحَرَ قَالَ لَا حَرَجَ ثُمَّ جَاءَهُ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي حَلَقْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ لَا حَرَجَ قَالَ فَمَا سُئِلَ عَنْ شَيْءٍ إِلَّا قَالَ لَا حَرَجَ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ ‏ ‏عَرَفَةَ ‏ ‏مَوْقِفٌ وَكُلُّ ‏ ‏مُزْدَلِفَةَ ‏ ‏مَوْقِفٌ ‏ ‏وَمِنًى ‏ ‏كُلُّهَا مَنْحَرٌ وَكُلُّ ‏ ‏فِجَاجِ ‏ ‏مَكَّةَ ‏ ‏طَرِيقٌ وَمَنْحَرٌ ‏","","",""],[1805,1805,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏كَانَ رَدِيفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏وَكَانَ يَسِيرُ ‏ ‏الْعَنَقَ ‏ ‏فَإِذَا أَتَى عَلَى فَجْوَةٍ ‏ ‏نَصَّ ‏","","",""],[1806,1806,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُقْبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏كُرَيْبٌ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏قَالَ ‏ ‏أَخْبِرْنِي عَشِيَّةَ رَدِفْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ فَعَلْتُمْ ‏ ‏أَوْ صَنَعْتُمْ ‏ ‏قَالَ ‏ ‏جِئْنَا الشِّعْبَ الَّذِي ‏ ‏يُنِيخُ ‏ ‏النَّاسُ فِيهِ ‏ ‏لِلْمُعَرَّسِ ‏ ‏فَأَنَاخَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاقَتَهُ ثُمَّ بَالَ ‏ ‏وَمَا قَالَ ‏ ‏أَهْرَاقَ الْمَاءَ ‏ ‏ثُمَّ دَعَا بِالْوَضُوءِ فَتَوَضَّأَ وُضُوءًا ‏ ‏لَيْسَ بِالسَّابِغِ ‏ ‏جِدًّا قُلْتُ يَا رَسُولَ اللَّهِ الصَّلَاةَ قَالَ ‏ ‏الصَّلَاةُ أَمَامَكَ قَالَ فَرَكِبَ حَتَّى قَدِمْنَا ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَأَقَامَ الْمَغْرِبَ ثُمَّ أَنَاخَ وَالنَّاسُ فِي مَنَازِلِهِمْ فَلَمْ يَحِلُّوا حَتَّى أَقَامَ الْعِشَاءَ الْآخِرَةَ فَصَلَّى ثُمَّ حَلَّ النَّاسُ قَالَ قُلْتُ أَخْبِرْنِي كَيْفَ فَعَلْتُمْ حِينَ أَصْبَحْتُمْ قَالَ رَدِفَهُ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏فَانْطَلَقْتُ أَنَا فِي ‏ ‏سُبَّاقِ ‏ ‏قُرَيْشٍ ‏ ‏عَلَى رِجْلَيَّ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبِ بْنِ أَبِي مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏نَحْوَهُ ‏","","",""],[1807,1807,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏يَعْنِي ‏ ‏بِجَمْعٍ ‏","","",""],[1808,1808,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الْمَغْرِبَ وَالْعِشَاءَ ‏ ‏بِالْمُزْدَلِفَةِ ‏ ‏لَمْ يُنَادِ فِي وَاحِدَةٍ مِنْهُمَا إِلَّا بِالْإِقَامَةِ وَلَمْ يُسَبِّحْ بَيْنَهُمَا وَلَا عَلَى إِثْرِ وَاحِدَةٍ مِنْهُمَا ‏","","",""],[1809,1809,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ شَوَّالٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهَا ‏ ‏أَنْ ‏ ‏تَنْفِرَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏بِلَيْلٍ ‏","","",""],[1810,1810,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَفْلَحُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اسْتَأْذَنَتْ ‏ ‏سَوْدَةُ بِنْتُ زَمْعَةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَأْذَنَ لَهَا ‏ ‏فَتَدْفَعَ ‏ ‏قَبْلَ أَنْ ‏ ‏يَدْفَعَ ‏ ‏فَأَذِنَ لَهَا ‏ ‏قَالَ ‏ ‏الْقَاسِمُ ‏ ‏وَكَانَتْ امْرَأَةً ثَبِطَةً قَالَ ‏ ‏الْقَاسِمُ ‏ ‏الثَّبِطَةُ الثَّقِيلَةُ ‏ ‏فَدَفَعَتْ ‏ ‏وَحُبِسْنَا مَعَهُ حَتَّى ‏ ‏دَفَعْنَا ‏ ‏بِدَفْعِهِ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَلَأَنْ أَكُونَ اسْتَأْذَنْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا اسْتَأْذَنَتْ ‏ ‏سَوْدَةُ ‏ ‏فَأَدْفَعَ قَبْلَ النَّاسِ أَحَبُّ إِلَيَّ مِنْ مَفْرُوحٍ بِهِ ‏","","",""],[1811,1811,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَعْمُرَ الدِّيلِيَّ ‏ ‏يَقُولُ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحَجِّ فَقَالَ ‏ ‏الْحَجُّ ‏ ‏عَرَفَاتٌ ‏ ‏أَوْ يَوْمُ ‏ ‏عَرَفَةَ ‏ ‏وَمَنْ أَدْرَكَ لَيْلَةَ ‏ ‏جَمْعٍ ‏ ‏قَبْلَ صَلَاةِ الصُّبْحِ فَقَدْ أَدْرَكَ وَقَالَ أَيَّامُ ‏ ‏مِنًى ‏ ‏ثَلَاثَةُ أَيَّامٍ ‏ { ‏فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ ‏}","","",""],[1812,1812,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ مُضَرِّسٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَوْقِفِ ‏ ‏عَلَى رُءُوسِ النَّاسِ فَقَالَ يَا رَسُولَ اللَّهِ جِئْتُ مِنْ ‏ ‏جَبَلَيْ طَيِّءٍ ‏ ‏أَكْلَلْتُ ‏ ‏مَطِيَّتِي ‏ ‏وَأَتْعَبْتُ نَفْسِي وَاللَّهِ إِنْ بَقِيَ جَبَلٌ إِلَّا وَقَفْتُ عَلَيْهِ فَهَلْ لِي مِنْ حَجٍّ قَالَ ‏ ‏مَنْ شَهِدَ مَعَنَا هَذِهِ الصَّلَاةَ وَقَدْ أَتَى ‏ ‏عَرَفَاتٍ ‏ ‏قَبْلَ ذَلِكَ لَيْلًا أَوْ نَهَارًا فَقَدْ قَضَى ‏ ‏تَفَثَهُ ‏ ‏وَتَمَّ حَجُّهُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ مُضَرِّسِ بْنِ حَارِثَةَ بْنِ لَامٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ‏ ‏نَحْوَهُ ‏","","",""],[1813,1813,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو غَسَّانَ مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏كَانَ أَهْلُ الْجَاهِلِيَّةِ ‏ ‏يُفِيضُونَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏بَعْدَ طُلُوعِ الشَّمْسِ وَكَانُوا يَقُولُونَ أَشْرِقْ ‏ ‏ثَبِيرُ ‏ ‏لَعَلَّنَا ‏ ‏نُغِيرُ ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَالَفَهُمْ فَدَفَعَ قَبْلَ طُلُوعِ الشَّمْسِ بِقَدْرِ صَلَاةِ الْمُسْفِرِينَ ‏ ‏أَوْ قَالَ الْمُشْرِقِينَ ‏ ‏بِصَلَاةِ ‏ ‏الْغَدَاةِ ‏","","",""],[1814,1814,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أَبَا مَعْبَدٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏الْفَضْلِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي عَشِيَّةِ ‏ ‏عَرَفَةَ ‏ ‏وَغَدَاةِ ‏ ‏جَمْعٍ ‏ ‏حِينَ ‏ ‏دَفَعُوا ‏ ‏عَلَيْكُمْ السَّكِينَةَ وَهُوَ كَافٌّ نَاقَتَهُ حَتَّى إِذَا دَخَلَ ‏ ‏مُحَسِّرًا ‏ ‏أَوْضَعَ ‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏بِإِسْنَادِهِ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏الْإِيضَاعُ ‏ ‏لِلْإِبِلِ ‏ ‏وَالْإِيجَافُ ‏ ‏لِلْخَيْلِ ‏","","",""],[1815,1815,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏وَسَالِمًا ‏ ‏كَلَّمَا ‏ ‏ابْنَ عُمَرَ ‏ ‏لَيَالِيَ نَزَلَ ‏ ‏الْحَجَّاجُ ‏ ‏بِابْنِ الزُّبَيْرِ ‏ ‏قَبْلَ أَنْ يُقْتَلَ فَقَالَا لَا يَضُرُّكَ أَنْ لَا تَحُجَّ الْعَامَ نَخَافُ أَنْ يُحَالَ بَيْنَكَ وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏فَقَالَ قَدْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعْتَمِرِينَ فَحَالَ كُفَّارُ ‏ ‏قُرَيْشٍ ‏ ‏دُونَ ‏ ‏الْبَيْتِ ‏ ‏فَنَحَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَدْيَهُ ‏ ‏وَحَلَقَ رَأْسَهُ ثُمَّ رَجَعَ فَأُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ عُمْرَةً فَإِنْ خُلِّيَ بَيْنِي وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏طُفْتُ وَإِنْ حِيلَ بَيْنِي وَبَيْنَهُ فَعَلْتُ كَمَا كَانَ فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ ‏ ‏فَأَهَلَّ ‏ ‏بِالْعُمْرَةِ مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏ثُمَّ سَارَ فَقَالَ إِنَّمَا شَأْنُهُمَا وَاحِدٌ أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ حَجًّا مَعَ عُمْرَتِي ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏فَطَافَ لَهُمَا طَوَافًا وَاحِدًا وَسَعَى لَهُمَا سَعْيًا وَاحِدًا ثُمَّ لَمْ يَحِلَّ حَتَّى جَاءَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏فَأَهْدَى ‏ ‏وَكَانَ يَقُولُ مَنْ جَمَعَ الْعُمْرَةَ وَالْحَجَّ ‏ ‏فَأَهَلَّ ‏ ‏بِهِمَا جَمِيعًا فَلَا يَحِلَّ حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا ‏ ‏يَوْمَ النَّحْرِ ‏","","",""],[1816,1816,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ الصَّوَّافِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ بْنِ عَمْرٍو الْأَنْصَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كُسِرَ ‏ ‏أَوْ عُرِجَ ‏ ‏فَقَدْ حَلَّ وَعَلَيْهِ حَجَّةٌ أُخْرَى ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏رَوَاهُ ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏وَمَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1817,1817,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَمْرَةَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏الضُّحَى وَبَعْدَ ذَلِكَ عِنْدَ زَوَالِ الشَّمْسِ ‏","","",""],[1818,1818,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْبَدَّاحِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْخَصَ لِرِعَاءِ الْإِبِلِ أَنْ يَرْمُوا ‏ ‏يَوْمَ النَّحْرِ ‏ ‏ثُمَّ يَرْمُوا الْغَدَ أَوْ مِنْ بَعْدِ الْغَدِ لِيَوْمَيْنِ ثُمَّ يَرْمُوا ‏ ‏يَوْمَ النَّفْرِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏مِنْهُمْ ‏ ‏مَنْ يَقُولُ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي الْبَدَّاحِ ‏","","",""],[1819,1819,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏أَنْ نَرْمِيَ ‏ ‏الْجَمْرَةَ ‏ ‏بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏","","",""],[1820,1820,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَمَوْا بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏وَأَوْضَعَ ‏ ‏فِي ‏ ‏وَادِي مُحَسِّرٍ ‏ ‏وَقَالَ عَلَيْكُمْ السَّكِينَةَ ‏","","",""],[1821,1821,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاذٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُنَا أَنْ نَرْمِيَ الْجِمَارَ بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُعَاذٍ ‏ ‏لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1822,1822,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏وَالْمُؤَمَّلُ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏أَيْمَنَ بْنِ نَابِلٍ ‏ ‏عَنْ ‏ ‏قُدَامَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَمَّارٍ الْكِلَابِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْمِي الْجِمَارَ عَلَى نَاقَةٍ ‏ ‏صَهْبَاءَ ‏ ‏لَيْسَ ثَمَّ ضَرْبٌ وَلَا طَرْدٌ وَلَا إِلَيْكَ إِلَيْكَ ‏","","",""],[1823,1823,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ هُوَ الْجَزَرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏الْفَضْلِ ‏ ‏قَالَ ‏ ‏كُنْتُ رِدْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[1824,1824,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَمَى ‏ ‏الْجَمْرَةَ ‏ ‏الَّتِي ‏ ‏تَلِي الْمَسْجِدَ ‏ ‏مَسْجِدَ مِنًى ‏ ‏يَرْمِيهَا بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ ثُمَّ تَقَدَّمَ أَمَامَهَا فَوَقَفَ مُسْتَقْبِلَ الْقِبْلَةِ رَافِعًا يَدَيْهِ وَكَانَ يُطِيلُ الْوُقُوفَ ثُمَّ يَأْتِي ‏ ‏الْجَمْرَةَ الثَّانِيَةَ ‏ ‏فَيَرْمِيهَا بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ ثُمَّ يَنْحَدِرُ مِنْ ذَاتِ الْيَسَارِ مِمَّا ‏ ‏يَلِي الْوَادِي رَافِعًا يَدَيْهِ يَدْعُو ثُمَّ يَأْتِي ‏ ‏الْجَمْرَةَ ‏ ‏الَّتِي عِنْدَ ‏ ‏الْعَقَبَةِ ‏ ‏فَيَرْمِيهَا بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ ثُمَّ يَنْصَرِفُ وَلَا يَقِفُ عِنْدَهَا ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ بِهَذَا الْحَدِيثِ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَفْعَلُهُ ‏","","",""],[1825,1825,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ هُوَ الْمَاجِشُونُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏هُوَ ‏ ‏ابْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَذْكُرُ إِلَّا الْحَجَّ فَلَمَّا جِئْنَا ‏ ‏سَرِفَ ‏ ‏طَمِثْتُ ‏ ‏فَلَمَّا كَانَ ‏ ‏يَوْمُ النَّحْرِ ‏ ‏طَهُرْتُ فَأَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَفَضْتُ ‏ ‏فَأُتِيَ بِلَحْمِ بَقَرٍ فَقُلْتُ مَا هَذَا قَالُوا ‏ ‏أَهْدَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نِسَائِهِ الْبَقَرَ ‏","","",""],[1826,1826,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ الْمَدِينِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏قَالَتْ أَخْبَرَتْنِي ‏ ‏أُمُّ عُثْمَانَ بِنْتُ أَبِي سُفْيَانَ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ عَلَى النِّسَاءِ حَلْقٌ إِنَّمَا عَلَى النِّسَاءِ التَّقْصِيرُ ‏","","",""],[1827,1827,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَحِمَ اللَّهُ الْمُحَلِّقِينَ قِيلَ وَالْمُقَصِّرِينَ قَالَ رَحِمَ اللَّهُ الْمُحَلِّقِينَ قَالَ فِي الرَّابِعَةِ وَالْمُقَصِّرِينَ ‏","","",""],[1828,1828,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ هُوَ ابْنُ أَبِي سَلَمَةَ الْمَاجِشُونُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ‏ ‏الْجَمْرَةِ ‏ ‏وَهُوَ يُسْأَلُ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ نَحَرْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ‏ ‏ارْمِ وَلَا حَرَجَ قَالَ آخَرُ يَا رَسُولَ اللَّهِ حَلَقْتُ قَبْلَ أَنْ أَنْحَرَ قَالَ انْحَرْ وَلَا حَرَجَ قَالَ فَمَا سُئِلَ عَنْ شَيْءٍ قُدِّمَ وَلَا أُخِّرَ إِلَّا قَالَ افْعَلْ وَلَا حَرَجَ ‏","","",""],[1829,1829,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ لِلنَّاسِ فِي حَجَّةِ الْوَدَاعِ فَقَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ حَلَقْتُ قَبْلَ أَنْ أَذْبَحَ قَالَ ‏ ‏لَا حَرَجَ قَالَ لَمْ أَشْعُرْ ذَبَحْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ لَا حَرَجَ فَلَمْ يُسْأَلْ يَوْمَئِذٍ عَنْ شَيْءٍ قُدِّمَ أَوْ أُخِّرَ إِلَّا قَالَ لَا حَرَجَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏أَنَا أَقُولُ بِهَذَا وَأَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏يُشَدِّدُونَ ‏","","",""],[1830,1830,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏نَاجِيَةَ الْأَسْلَمِيِّ ‏ ‏صَاحِبِ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ أَصْنَعُ بِمَا ‏ ‏عَطِبَ ‏ ‏مِنْ ‏ ‏الْهَدْيِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ ‏ ‏بَدَنَةٍ ‏ ‏عَطِبَتْ فَانْحَرْهَا ثُمَّ أَلْقِ نَعْلَهَا فِي دَمِهَا ثُمَّ خَلِّ بَيْنَهَا وَبَيْنَ النَّاسِ فَلْيَأْكُلُوهَا ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏نَاجِيَةَ ‏ ‏نَحْوَهُ ‏","","",""],[1831,1831,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَهْدَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّةً غَنَمًا ‏","","",""],[1832,1832,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَسَّانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏ثُمَّ دَعَا ‏ ‏بِبَدَنَةٍ ‏ ‏فَأَشْعَرَهَا ‏ ‏مِنْ صَفْحَةِ سَنَامِهَا الْأَيْمَنِ ثُمَّ ‏ ‏سَلَتَ ‏ ‏الدَّمَ عَنْهَا ‏ ‏وَقَلَّدَهَا ‏ ‏نَعْلَيْنِ ثُمَّ أُتِيَ بِرَاحِلَتِهِ فَلَمَّا قَعَدَ عَلَيْهَا وَاسْتَوَتْ عَلَى ‏ ‏الْبَيْدَاءِ ‏ ‏أَهَلَّ ‏ ‏بِالْحَجِّ ‏","","",""],[1833,1833,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ انْتَهَى إِلَى رَجُلٍ يَسُوقُ ‏ ‏بَدَنَتَهُ ‏ ‏قَالَ ‏ ‏ارْكَبْهَا فَقَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا وَيْحَكَ ‏","","",""],[1834,1834,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ رَأَى رَجُلًا قَدْ ‏ ‏أَنَاخَ ‏ ‏بَدَنَةً ‏ ‏فَقَالَ ‏ ‏ابْعَثْهَا قِيَامًا مُقَيَّدَةً سُنَّةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1835,1835,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏أَبِي قُرَّةَ هُوَ مُوسَى بْنُ طَارِقٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ رَجَعَ مِنْ عُمْرَةِ ‏ ‏الْجِعْرَانَةِ ‏ ‏بَعَثَ ‏ ‏أَبَا بَكْرٍ ‏ ‏عَلَى الْحَجِّ فَأَقْبَلْنَا مَعَهُ حَتَّى إِذَا كُنَّا ‏ ‏بِالْعَرْجِ ‏ ‏ثُوِّبَ ‏ ‏بِالصُّبْحِ فَلَمَّا اسْتَوَى لِيُكَبِّرَ سَمِعَ ‏ ‏الرَّغْوَةَ ‏ ‏خَلْفَ ظَهْرِهِ فَوَقَفَ عَنْ التَّكْبِيرِ فَقَالَ هَذِهِ ‏ ‏رَغْوَةُ ‏ ‏نَاقَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَدْعَاءِ لَقَدْ بَدَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْحَجِّ فَلَعَلَّهُ أَنْ يَكُونَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُصَلِّيَ مَعَهُ فَإِذَا ‏ ‏عَلِيٌّ ‏ ‏عَلَيْهَا فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَمِيرٌ أَمْ رَسُولٌ قَالَ لَا بَلْ رَسُولٌ ‏ ‏أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَرَاءَةٌ ‏ ‏أَقْرَؤُهَا عَلَى النَّاسِ فِي مَوَاقِفِ الْحَجِّ فَقَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏فَلَمَّا كَانَ قَبْلَ ‏ ‏التَّرْوِيَةِ ‏ ‏بِيَوْمٍ قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَخَطَبَ النَّاسَ فَحَدَّثَهُمْ عَنْ ‏ ‏مَنَاسِكِهِمْ ‏ ‏حَتَّى إِذَا فَرَغَ قَامَ ‏ ‏عَلِيٌّ ‏ ‏فَقَرَأَ عَلَى النَّاسِ ‏ ‏بَرَاءَةٌ ‏ ‏حَتَّى خَتَمَهَا ثُمَّ خَرَجْنَا مَعَهُ حَتَّى إِذَا كَانَ يَوْمُ ‏ ‏عَرَفَةَ ‏ ‏قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَخَطَبَ النَّاسَ فَحَدَّثَهُمْ عَنْ مَنَاسِكِهِمْ حَتَّى إِذَا فَرَغَ قَامَ ‏ ‏عَلِيٌّ ‏ ‏فَقَرَأَ عَلَى النَّاسِ ‏ ‏بَرَاءَةٌ ‏ ‏حَتَّى خَتَمَهَا ثُمَّ كَانَ يَوْمُ النَّحْرِ ‏ ‏فَأَفَضْنَا ‏ ‏فَلَمَّا رَجَعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏خَطَبَ النَّاسَ فَحَدَّثَهُمْ عَنْ ‏ ‏إِفَاضَتِهِمْ ‏ ‏وَعَنْ نَحْرِهِمْ وَعَنْ ‏ ‏مَنَاسِكِهِمْ ‏ ‏فَلَمَّا فَرَغَ قَامَ ‏ ‏عَلِيٌّ ‏ ‏فَقَرَأَ عَلَى النَّاسِ ‏ ‏بَرَاءَةٌ ‏ ‏حَتَّى خَتَمَهَا فَلَمَّا كَانَ ‏ ‏يَوْمُ النَّفْرِ ‏ ‏الْأَوَّلُ قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَخَطَبَ النَّاسَ فَحَدَّثَهُمْ كَيْفَ ‏ ‏يَنْفِرُونَ ‏ ‏وَكَيْفَ يَرْمُونَ فَعَلَّمَهُمْ ‏ ‏مَنَاسِكَهُمْ ‏ ‏فَلَمَّا فَرَغَ قَامَ ‏ ‏عَلِيٌّ ‏ ‏فَقَرَأَ ‏ ‏بَرَاءَةٌ ‏ ‏عَلَى النَّاسِ حَتَّى خَتَمَهَا ‏","","",""],[1836,1836,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو حَاتِمٍ أَشْهَلُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ ذَلِكَ الْيَوْمُ قَعَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَعِيرٍ ‏ ‏لَا أَدْرِي جَمَلٌ أَوْ نَاقَةٌ ‏ ‏وَأَخَذَ إِنْسَانٌ ‏ ‏بِخِطَامِهِ ‏ ‏أَوْ قَالَ بِزِمَامِهِ ‏ ‏فَقَالَ أَيُّ يَوْمٍ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ فَقَالَ أَلَيْسَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏قُلْنَا بَلَى قَالَ فَأَيُّ شَهْرٍ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ فَقَالَ أَلَيْسَ ذَا الْحِجَّةِ قُلْنَا بَلَى قَالَ فَأَيُّ بَلَدٍ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ فَقَالَ أَلَيْسَ ‏ ‏الْبَلْدَةَ ‏ ‏قُلْنَا بَلَى قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ بَيْنَكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا أَلَا لِيُبَلِّغْ الشَّاهِدُ الْغَائِبَ فَإِنَّ الشَّاهِدَ عَسَى أَنْ يُبَلِّغَ مَنْ هُوَ أَوْعَى مِنْهُ ‏","","",""],[1837,1837,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏حَاضَتْ ‏ ‏صَفِيَّةُ ‏ ‏فَلَمَّا كَانَتْ ‏ ‏لَيْلَةُ النَّفْرِ ‏ ‏قَالَتْ أَيْ حَلْقَى أَيْ عَقْرَى بِلُغَةٍ لَهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَسْتِ قَدْ طُفْتِ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏قَالَتْ بَلَى قَالَ فَارْكَبِي ‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِنَحْوِهِ ‏","","",""],[1838,1838,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْبَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ يُثَيْعٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا ‏ ‏عَلِيًّا ‏ ‏بِأَيِّ شَيْءٍ بُعِثْتَ قَالَ ‏ ‏بُعِثْتُ بِأَرْبَعٍ لَا يَدْخُلُ الْجَنَّةَ إِلَّا نَفْسٌ مُؤْمِنَةٌ وَلَا يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏عُرْيَانٌ وَلَا يَجْتَمِعُ مُسْلِمٌ وَكَافِرٌ فِي الْحَجِّ بَعْدَ عَامِهِمْ هَذَا وَمَنْ كَانَ بَيْنَهُ وَبَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهْدٌ فَعَهْدُهُ إِلَى مُدَّتِهِ وَمَنْ لَمْ يَكُنْ لَهُ عَهْدٌ فَهِيَ أَرْبَعَةُ أَشْهُرٍ يَقُولُ بَعْدَ ‏ ‏يَوْمِ النَّحْرِ ‏ ‏أَجَلُهُمْ عِشْرِينَ مِنْ ذِي الْحِجَّةِ فَاقْتُلُوهُمْ بَعْدَ الْأَرْبَعَةِ ‏","","",""],[1839,1839,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو قَزَعَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُهَاجِرًا ‏ ‏يَقُولُ ‏ ‏سُئِلَ ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ رَفْعِ الْأَيْدِي عِنْدَ ‏ ‏الْبَيْتِ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا كَانَ يَصْنَعُ ذَلِكَ ‏ ‏الْيَهُودُ ‏ ‏حَجَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَصَنَعْنَا ذَاكَ ‏","","",""],[1840,1840,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ مُدْرِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ اسْتَنْصَتَ النَّاسَ فِي حَجَّةِ الْوَدَاعِ ثُمَّ قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[1841,1841,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏قَالَ وَسَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏سَعَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَنَحْنُ نَسْتُرُهُ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏أَنْ يُصِيبَهُ أَحَدٌ بِحَجَرٍ أَوْ بِرَمْيَةٍ ‏","","",""],[1842,1842,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏عَلِيًّا ‏ ‏وَعُثْمَانَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏وَعُثْمَانُ ‏ ‏يَنْهَى عَنْ ‏ ‏الْمُتْعَةِ ‏ ‏فَلَمَّا رَأَى ذَلِكَ ‏ ‏عَلِيٌّ ‏ ‏أَهَلَّ ‏ ‏بِهِمَا جَمِيعًا فَقَالَ لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا فَقَالَ تَرَانِي أَنْهَى عَنْهُ وَتَفْعَلُهُ فَقَالَ لَمْ أَكُنْ لِأَدَعَ سُنَّةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَوْلِ أَحَدٍ مِنْ النَّاسِ ‏","","",""],[1843,1843,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ بِعُمْرَةٍ وَحَجٍّ ‏","","",""],[1844,1844,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهَلَّ بِهِمَا جَمِيعًا ‏ ‏فَلَقِيتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَأَخْبَرْتُهُ بِقَوْلِ ‏ ‏أَنَسٍ ‏ ‏فَقَالَ إِنَّمَا أَهَلَّ بِالْحَجِّ فَرَجَعْتُ إِلَى ‏ ‏أَنَسٍ ‏ ‏فَأَخْبَرْتُهُ بِقَوْلِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَ مَا يَعُدُّونَا إِلَّا صِبْيَانًا ‏","","",""],[1845,1845,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَاهُ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏إِنْ وَلِيتُمْ هَذَا الْأَمْرَ فَلَا تَمْنَعُوا أَحَدًا طَافَ أَوْ صَلَّى أَيَّ سَاعَةٍ شَاءَ مِنْ لَيْلٍ أَوْ نَهَارٍ ‏","","",""],[1846,1846,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاتَ ‏ ‏بِذِي طُوًى ‏ ‏حَتَّى أَصْبَحَ ثُمَّ دَخَلَ ‏ ‏مَكَّةَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَفْعَلُهُ ‏","","",""],[1847,1847,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدْخُلُ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏الثَّنِيَّةِ الْعُلْيَا ‏ ‏وَيَخْرُجُ مِنْ ‏ ‏الثَّنِيَّةِ السُّفْلَى ‏","","",""],[1848,1848,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَدْخَلَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏وَاسْتَوَتْ بِهِ نَاقَتُهُ ‏ ‏أَهَلَّ ‏ ‏مِنْ مَسْجِدِ ‏ ‏ذِي الْحُلَيْفَةِ ‏","","",""],[1849,1849,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ أَحْمَدَ بْنِ أَبِي خَلَفٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ قَالَ فِي الْمُحْرِمِ إِذَا اشْتَكَى عَيْنَيْهِ ‏ ‏يَضْمِدُهَا ‏ ‏بِالصَّبِرِ ‏","","",""],[1850,1850,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَصَلَّى عِنْدَ ‏ ‏الْمَقَامِ ‏ ‏رَكْعَتَيْنِ ثُمَّ خَرَجَ إِلَى ‏ ‏الصَّفَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَحَدَّثَنِي ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏هِيَ السُّنَّةُ ‏","","",""],[1851,1851,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّاسُ يَنْصَرِفُونَ فِي كُلِّ وَجْهٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَنْفِرَنَّ ‏ ‏أَحَدٌ حَتَّى يَكُونَ آخِرُ عَهْدِهِ ‏ ‏بِالْبَيْتِ ‏","","",""],[1852,1852,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رُخِّصَ لِلْحَائِضِ أَنْ ‏ ‏تَنْفِرَ ‏ ‏إِذَا ‏ ‏أَفَاضَتْ ‏ ‏قَالَ وَسَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَامَ الْأَوَّلِ أَنَّهَا لَا ‏ ‏تَنْفِرُ ‏ ‏ثُمَّ سَمِعْتُهُ يَقُولُ ‏ ‏تَنْفِرُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ لَهُنَّ ‏","","",""],[1853,1853,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏طَاوُسٌ الْيَمَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏وَهُوَ يُسْأَلُ عَنْ حَبْسِ النِّسَاءِ عَنْ الطَّوَافِ ‏ ‏بِالْبَيْتِ ‏ ‏إِذَا حِضْنَ قَبْلَ ‏ ‏النَّفْرِ ‏ ‏وَقَدْ ‏ ‏أَفَضْنَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏فَقَالَ إِنَّ ‏ ‏عَائِشَةَ ‏ ‏كَانَتْ ‏ ‏تَذْكُرُ رُخْصَةً لِلنِّسَاءِ وَذَلِكَ قَبْلَ مَوْتِ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏بِعَامٍ ‏","","",""],[1854,1854,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏يَا أُمَّ الْمُؤْمِنِينَ إِنَّ رِجَالًا يَبْعَثُ أَحَدُهُمْ ‏ ‏بِالْهَدْيِ ‏ ‏مَعَ الرَّجُلِ فَيَقُولُ إِذَا بَلَغْتَ مَكَانَ كَذَا وَكَذَا فَقَلِّدْهُ فَإِذَا بَلَغَ ذَلِكَ الْمَكَانَ لَمْ يَزَلْ مُحْرِمًا حَتَّى يَحِلَّ النَّاسُ قَالَ فَسَمِعْتُ صَفْقَتَهَا بِيَدِهَا مِنْ وَرَاءِ الْحِجَابِ وَقَالَتْ لَقَدْ كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏الْقَلَائِدَ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ ‏ ‏بِالْهَدْيِ ‏ ‏إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏مَا يَحْرُمُ عَلَيْهِ شَيْءٌ مِمَّا يَحِلُّ لِلرَّجُلِ مِنْ أَهْلِهِ حَتَّى يَرْجِعَ النَّاسُ ‏","","",""],[1855,1855,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏وَعَمْرَةُ بِنْتُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ ‏ ‏بِهَدْيِهِ ‏ ‏مُقَلَّدَةً ‏ ‏وَيُقِيمُ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَلَا يَجْتَنِبُ شَيْئًا حَتَّى يُنْحَرَ ‏ ‏هَدْيُهُ ‏","","",""],[1856,1856,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏مُسَيْكَةَ ‏ ‏وَأَثْنَى عَلَيْهَا خَيْرًا ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَلَا نَبْنِي لَكَ ‏ ‏بِمِنًى ‏ ‏بِنَاءً يُظِلُّكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏مِنًى ‏ ‏مُنَاخُ ‏ ‏مَنْ سَبَقَ ‏","","",""],[1857,1857,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏مَكَّةَ ‏ ‏عَامَ الْفَتْحِ وَعَلَى رَأْسِهِ ‏ ‏مِغْفَرٌ ‏ ‏فَلَمَّا نَزَعَهُ جَاءَهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏هَذَا ‏ ‏ابْنُ خَطَلٍ ‏ ‏مُتَعَلِّقٌ بِأَسْتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوهُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ خَالِدٍ ‏ ‏وَقُرِئَ عَلَى ‏ ‏مَالِكٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ مُحْرِمًا ‏","","",""],[1858,1858,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمَّارٍ الدُّهْنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏حِينَ افْتَتَحَهَا وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ بِغَيْرِ إِحْرَامٍ ‏ ‏قَالَ ‏ ‏إِسْمَعِيلُ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏كَانَ مَعَ أَبِيهِ ‏","","",""],[1859,1859,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْحَسَنُ بْنُ مُسْلِمٍ ‏ ‏وَعَبْدُ الْكَرِيمِ الْجَزَرِيُّ ‏ ‏أَنَّ ‏ ‏مُجَاهِدًا ‏ ‏أَخْبَرَهُمَا أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَلِيًّا ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ ‏ ‏أَنْ يَقُومَ عَلَى ‏ ‏بُدْنِهِ ‏ ‏وَأَنْ يَقْسِمَ ‏ ‏بُدْنَهُ ‏ ‏كُلَّهَا لُحُومَهَا وَجُلُودَهَا ‏ ‏وَجِلَالَهَا ‏ ‏وَلَا يُعْطِيَ فِي جِزَارَتِهَا مِنْهَا شَيْئًا ‏","","",""],[1860,1860,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبُعِ فَقَالَ ‏ ‏هُوَ صَيْدٌ وَفِيهِ كَبْشٌ إِذَا أَصَابَهُ الْمُحْرِمُ ‏","","",""],[1861,1861,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي عَمَّارٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ الضَّبُعِ آكُلُهُ قَالَ نَعَمْ قُلْتُ هُوَ صَيْدٌ قَالَ نَعَمْ قُلْتُ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏مَا تَقُولُ فِي الضَّبُعِ تَأْكُلُهُ ‏ ‏قَالَ ‏ ‏أَنَا أَكْرَهُ أَكْلَهُ ‏","","",""],[1862,1862,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏الْعَّبَاسَ بْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏اسْتَأْذَنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَبِيتَ ‏ ‏بِمَكَّةَ ‏ ‏لَيَالِيَ ‏ ‏مِنًى ‏ ‏مِنْ أَجْلِ سِقَايَتِهِ فَأَذِنَ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يُونُسَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏نَحْوَهُ ‏","","",""],[1863,1863,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏ضَحَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ وَيُسَمِّي وَيُكَبِّرُ لَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَاضِعًا عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَدَمَهُ ‏ ‏قُلْتُ أَنْتَ سَمِعْتَهُ قَالَ نَعَمْ ‏","","",""],[1864,1864,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي عَيَّاشٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏ضَحَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَبْشَيْنِ فِي يَوْمِ الْعِيدِ فَقَالَ حِينَ وَجَّهَهُمَا ‏ { ‏إِنِّي وَجَّهْتُ ‏ ‏وَجْهِيَ لِلَّذِي ‏ ‏فَطَرَ ‏ ‏السَّمَوَاتِ وَالْأَرْضَ ‏ ‏حَنِيفًا ‏ ‏وَمَا أَنَا مِنْ الْمُشْرِكِينَ ‏} { ‏إِنَّ صَلَاتِي ‏ ‏وَنُسُكِي ‏ ‏وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ ‏} ‏اللَّهُمَّ إِنَّ هَذَا مِنْكَ وَلَكَ عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏وَأُمَّتِهِ ثُمَّ سَمَّى اللَّهَ وَكَبَّرَ وَذَبَحَ ‏","","",""],[1865,1865,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏خَالِدٌ يَعْنِي ابْنَ يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُسْلِمٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَرَادَ أَنْ يُضَحِّيَ فَلَا يُقَلِّمْ أَظْفَارَهُ وَلَا يَحْلِقْ شَيْئًا مِنْ شَعْرِهِ فِي الْعَشْرِ الْأُوَلِ مِنْ ذِي الْحِجَّةِ ‏","","",""],[1866,1866,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دَخَلَتْ الْعَشْرُ وَأَرَادَ أَحَدُكُمْ أَنْ يُضَحِّيَ فَلَا يَمَسَّ مِنْ شَعْرِهِ وَلَا أَظْفَارِهِ شَيْئًا ‏","","",""],[1867,1867,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ فَيْرُوزَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يُتَّقَى مِنْ الضَّحَايَا قَالَ ‏ ‏الْعَوْرَاءُ الْبَيِّنُ عَوَرُهَا وَالْعَرْجَاءُ الْبَيِّنُ ‏ ‏ظَلْعُهَا ‏ ‏وَالْمَرِيضَةُ الْبَيِّنُ مَرَضُهَا ‏ ‏وَالْعَجْفَاءُ ‏ ‏الَّتِي لَا ‏ ‏تُنْقِي ‏","","",""],[1868,1868,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ فَيْرُوزَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْبَرَاءَ ‏ ‏عَمَّا نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْأَضَاحِيِّ فَقَالَ ‏ ‏أَرْبَعٌ لَا يُجْزِئْنَ الْعَوْرَاءُ الْبَيِّنُ عَوَرُهَا وَالْعَرْجَاءُ الْبَيِّنُ ‏ ‏ظَلْعُهَا ‏ ‏وَالْمَرِيضَةُ الْبَيِّنُ مَرَضُهَا وَالْكَسِيرُ الَّتِي لَا ‏ ‏تُنْقِي ‏ ‏قَالَ قُلْتُ ‏ ‏لِلْبَرَاءِ ‏ ‏فَإِنِّي أَكْرَهُ أَنْ يَكُونَ فِي السِّنِّ نَقْصٌ وَفِي الْأُذُنِ نَقْصٌ وَفِي الْقَرْنِ نَقْصٌ قَالَ ‏ ‏فَمَا كَرِهْتَ فَدَعْهُ وَلَا تُحَرِّمْهُ عَلَى أَحَدٍ ‏","","",""],[1869,1869,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُجَيَّةَ بْنَ عَدِيٍّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏وَسَأَلَهُ رَجُلٌ فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ الْبَقَرَةُ فَقَالَ عَنْ سَبْعَةٍ قُلْتُ الْقَرْنُ قَالَ لَا يَضُرُّكَ قَالَ قُلْتُ الْعَرَجُ قَالَ إِذَا بَلَغَتْ ‏ ‏الْمَنْسَكَ ‏ ‏ثُمَّ قَالَ أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَ وَالْأُذُنَ ‏","","",""],[1870,1870,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ النُّعْمَانِ الصَّائِدِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَ وَالْأُذُنَ وَأَنْ لَا نُضَحِّيَ بِمُقَابَلَةٍ وَلَا مُدَابَرَةٍ وَلَا خَرْقَاءَ وَلَا ‏ ‏شَرْقَاءَ فَالْمُقَابَلَةُ مَا قُطِعَ طَرَفُ أُذُنِهَا وَالْمُدَابَرَةُ مَا قُطِعَ مِنْ جَانِبِ الْأُذُنِ وَالْخَرْقَاءُ الْمَثْقُوبَةُ ‏ ‏وَالشَّرْقَاءُ الْمَشْقُوقَةُ ‏","","",""],[1871,1871,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏بَعْجَةَ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَايَا بَيْنَ أَصْحَابِهِ فَأَصَابَنِي ‏ ‏جَذَعٌ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّهَا ‏ ‏صَارَتْ لِي ‏ ‏جَذَعَةٌ ‏ ‏فَقَالَ ضَحِّ بِهَا ‏","","",""],[1872,1872,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏أَعْطَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَمًا أَقْسِمُهَا عَلَى أَصْحَابِهِ فَقَسَمْتُهَا وَبَقِيَ مِنْهَا عَتُودٌ فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ضَحِّ بِهِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏الْعَتُودُ ‏ ‏الْجَذَعُ ‏ ‏مِنْ الْمَعْزِ ‏","","",""],[1873,1873,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَحَرْنَا يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏سَبْعِينَ ‏ ‏بَدَنَةً ‏ ‏الْبَدَنَةُ ‏ ‏عَنْ سَبْعَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرِكُوا فِي ‏ ‏الْهَدْيِ ‏","","",""],[1874,1874,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَحَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَقَرَةَ عَنْ سَبْعَةٍ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏تَقُولُ بِهِ قَالَ نَعَمْ ‏","","",""],[1875,1875,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُحُومِ الْأَضَاحِيِّ أَوْ قَالَ ‏ ‏لَا تَأْكُلُوا لُحُومَ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ ‏","","",""],[1876,1876,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ هُوَ ابْنُ عَبْدِ اللَّهِ الطَّحَّانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏نُبَيْشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّا كُنَّا نَهَيْنَاكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ أَنْ تَأْكُلُوهَا فَوْقَ ثَلَاثَةِ أَيَّامٍ كَيْ تَسَعَكُمْ فَقَدْ جَاءَ اللَّهُ بِالسَّعَةِ فَكُلُوا وَادَّخِرُوا وَاتَّجِرُوا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏اتَّجِرُوا اطْلُبُوا فِيهِ الْأَجْرَ ‏","","",""],[1877,1877,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَهَى عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ فَلَمَّا كَانَ الْعَامُ الْقَابِلُ وَضَحَّى النَّاسُ قُلْتُ يَا رَسُولَ اللَّهِ إِنْ كَانَتْ هَذِهِ الْأَضَاحِيُّ لَتَرْفُقُ بِالنَّاسِ كَانُوا يَدَّخِرُونَ مِنْ لُحُومِهَا وَوَدَكِهَا قَالَ ‏ ‏فَمَا يَمْنَعُهُمْ مِنْ ذَلِكَ الْيَوْمَ قُلْتُ يَا نَبِيَّ اللَّهِ ‏ ‏أَوَ لَمْ تَنْهَهُمْ عَامَ أَوَّلَ عَنْ أَنْ يَأْكُلُوا لُحُومَهَا فَوْقَ ثَلَاثٍ فَقَالَ إِنَّمَا نَهَيْتُ عَنْ ذَلِكَ لِلْحَاضِرَةِ الَّتِي حَضَرَتْهُمْ مِنْ أَهْلِ الْبَادِيَةِ ‏ ‏لِيَنُثُّوا ‏ ‏لُحُومَهَا فِيهِمْ فَأَمَّا الْآنَ فَلْيَأْكُلُوا وَلْيَدَّخِرُوا ‏","","",""],[1878,1878,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْوَلِيدِ الزَّبِيدِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ثَوْبَانَ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ ‏ ‏بِمِنًى ‏ ‏أَصْلِحْ لَنَا مِنْ هَذَا اللَّحْمِ فَأَصْلَحْتُ لَهُ مِنْهُ فَلَمْ يَزَلْ يَأْكُلُ مِنْهُ حَتَّى بَلَغْنَا ‏ ‏الْمَدِينَةَ ‏","","",""],[1879,1879,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏إِنْ كُنَّا لَنَتَزَوَّدُ مِنْ ‏ ‏مَكَّةَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي لُحُومَ الْأَضَاحِيِّ ‏","","",""],[1880,1880,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَزُبَيْدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ ‏ ‏أَبَا بُرْدَةَ بْنَ نِيَارٍ ‏ ‏ضَحَّى قَبْلَ أَنْ يُصَلِّيَ فَلَمَّا صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَاهُ فَذَكَرَ لَهُ مَا فَعَلَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا شَاتُكَ شَاةُ لَحْمٍ فَقَالَ يَا رَسُولَ اللَّهِ عِنْدِي عَنَاقٌ لِي جَذَعَةٌ مِنْ الْمَعْزِ هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْنِ قَالَ فَضَحِّ بِهَا وَلَا تُجْزِئُ عَنْ أَحَدٍ بَعْدَكَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏قُرِئَ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَمَنْ ذَبَحَ بَعْدَ الصَّلَاةِ وَالْإِمَامُ يَخْطُبُ أَجْزَأَهُ ‏","","",""],[1881,1881,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَلِيٍّ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏أَنَّ رَجُلًا ذَبَحَ قَبْلَ أَنْ يَنْصَرِفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ أَنْ يُعِيدَ ‏","","",""],[1882,1882,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏فَرَعَ ‏ ‏وَلَا ‏ ‏عَتِيرَةَ ‏","","",""],[1883,1883,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ الْعُقَيْلِيِّ لَقِيطِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّا كُنَّا ‏ ‏نَذْبَحُ فِي رَجَبٍ فَمَا ‏ ‏تَرَى قَالَ لَا بَأْسَ بِذَلِكَ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏لَا أَدَعُهُ أَبَدًا ‏","","",""],[1884,1884,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏حَبِيبَةَ بِنْتِ مَيْسَرَةَ بْنِ أَبِي خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُرْزٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏الْعَقِيقَةِ ‏ ‏عَنْ الْغُلَامِ شَاتَانِ ‏ ‏مُكَافِئَتَانِ ‏ ‏وَعَنْ الْجَارِيَةِ شَاةٌ ‏","","",""],[1885,1885,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَةٌ ‏ ‏فَأَهْرِيقُوا عَنْهُ الدَّمَ ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[1886,1886,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏سِبَاعِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُرْزٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْغُلَامِ شَاتَانِ مِثْلَانِ وَعَنْ الْجَارِيَةِ شَاةٌ ‏","","",""],[1887,1887,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ غُلَامٍ رَهِينَةٌ ‏ ‏بِعَقِيقَتِهِ ‏ ‏يُذْبَحُ عَنْهُ يَوْمَ سَابِعِهِ وَيُحْلَقُ ‏ ‏وَيُدَمَّى ‏ ‏وَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَصِفُ الدَّمَ فَيَقُولُ إِذَا ذُبِحَتْ ‏ ‏الْعَقِيقَةُ ‏ ‏تُؤْخَذُ صُوفَةٌ فَيُسْتَقْبَلُ بِهَا ‏ ‏أَوْدَاجُ ‏ ‏الذَّبِيحَةِ ثُمَّ تُوضَعُ عَلَى ‏ ‏يَافُوخِ ‏ ‏الصَّبِيِّ حَتَّى إِذَا سَالَ شَبَهُ الْخَيْطِ غُسِلَ رَأْسُهُ ثُمَّ حُلِقَ بَعْدُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏بِهَذَا الْحَدِيثِ قَالَ وَيُسَمَّى ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَلَا أُرَاهُ وَاجِبًا ‏","","",""],[1888,1888,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏حَفِظْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اثْنَتَيْنِ قَالَ ‏ ‏إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ ثُمَّ لِيُرِحْ ذَبِيحَتَهُ ‏","","",""],[1889,1889,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ امْرَأَةً كَانَتْ ‏ ‏تَرْعَى لِآلِ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏غَنَمًا ‏ ‏بِسَلْعٍ ‏ ‏فَخَافَتْ عَلَى شَاةٍ مِنْهَا أَنْ تَمُوتَ فَأَخَذَتْ حَجَرًا فَذَبَحَتْهَا بِهِ وَإِنَّ ذَلِكَ ذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهَا ‏","","",""],[1890,1890,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏وَعُثْمَانُ بْنُ عُمَرَ ‏ ‏وَعَفَّانُ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعُشَرَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَمَا تَكُونُ ‏ ‏الذَّكَاةُ ‏ ‏إِلَّا فِي الْحَلْقِ ‏ ‏وَاللَّبَّةِ ‏ ‏فَقَالَ ‏ ‏لَوْ طَعَنْتَ فِي فَخِذِهَا لَأَجْزَأَ عَنْكَ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏حَمَلْنَاهُ عَلَى ‏ ‏الْمُتَرَدِّي ‏","","",""],[1891,1891,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْمِنْهَالُ بْنُ عَمْرٍو ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يَقُولُ ‏ ‏خَرَجْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَإِذَا غِلْمَةٌ يَرْمُونَ دَجَاجَةً فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏مَنْ فَعَلَ هَذَا فَتَفَرَّقُوا فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ مَنْ ‏ ‏يُمَثِّلُ ‏ ‏بِالْحَيَوَانِ ‏","","",""],[1892,1892,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ تِعْلَى ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏صَبْرِ ‏ ‏الدَّابَّةِ ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏لَوْ كَانَتْ دَجَاجَةً مَا ‏ ‏صَبَرْتُهَا ‏","","",""],[1893,1893,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏نَهَى عَنْ الْمُجَثَّمَةِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏الْمُجَثَّمَةُ ‏ ‏الْمَصْبُورَةُ ‏","","",""],[1894,1894,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحِيمِ هُوَ ابْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ قَوْمًا قَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَوْمًا يَأْتُونَا بِاللَّحْمِ لَا نَدْرِي أَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ أَمْ لَا فَقَالَ ‏ ‏سَمُّوا أَنْتُمْ وَكُلُوا وَكَانُوا حَدِيثَ عَهْدٍ بِجَاهِلِيَّةٍ ‏","","",""],[1895,1895,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ بَعِيرًا ‏ ‏نَدَّ ‏ ‏وَلَيْسَ فِي الْقَوْمِ إِلَّا خَيْلٌ يَسِيرَةٌ فَرَمَاهُ رَجُلٌ بِسَهْمٍ فَحَبَسَهُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِهَذِهِ الْبَهَائِمِ ‏ ‏أَوَابِدَ ‏ ‏كَأَوَابِدِ ‏ ‏الْوَحْشِ فَمَا غَلَبَكُمْ مِنْهَا فَاصْنَعُوا بِهِ هَكَذَا ‏","","",""],[1896,1896,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو هُوَ ابْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏صُهَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ عُصْفُورًا بِغَيْرِ حَقِّهِ سَأَلَهُ اللَّهُ عَنْهُ يَوْمَ الْقِيَامَةِ قِيلَ وَمَا حَقُّهُ قَالَ أَنْ تَذْبَحَهُ فَتَأْكُلَهُ ‏","","",""],[1897,1897,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ بَشِيرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ذَكَاةُ ‏ ‏الْجَنِينِ ‏ ‏ذَكَاةُ ‏ ‏أُمِّهِ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏يُؤْكَلُ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1898,1898,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ثَعْلَبَةَ الْخُشَنِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَكْلِ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السَّبُعِ ‏","","",""],[1899,1899,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏ابْنُ عَمِّ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ثَعْلَبَةَ الْخُشَنِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْخَطْفَةِ ‏ ‏وَالْمُجَثَّمَةِ ‏ ‏وَالنُّهْبَةِ ‏ ‏وَعَنْ أَكْلِ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ ‏","","",""],[1900,1900,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَكْلِ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ وَكُلِّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ ‏","","",""],[1901,1901,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ جُلُودِ السِّبَاعِ أَنْ تُفْتَرَشَ ‏ ‏أَخْبَرَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[1902,1902,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ الْأَسْقِيَةِ ‏ ‏فَقَالَ ‏ ‏مَا أَدْرِي مَا أَقُولُ لَكَ غَيْرَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا ‏ ‏إِهَابٍ ‏ ‏دُبِغَ ‏ ‏فَقَدْ طَهُرَ ‏","","",""],[1903,1903,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ جُلُودِ الْمَيْتَةِ ‏ ‏فَقَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِبَاغُهَا ‏ ‏طَهُورُهَا ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ عَبْدِ اللَّهِ ‏ ‏تَقُولُ بِهَذَا ‏ ‏قَالَ ‏ ‏نَعَمْ إِذَا كَانَ يُؤْكَلُ لَحْمُهُ ‏","","",""],[1904,1904,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُسْتَمْتَعَ بِجُلُودِ الْمَيْتَةِ ‏","","",""],[1905,1905,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَاتَتْ شَاةٌ ‏ ‏لِمَيْمُونَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ اسْتَمْتَعْتُمْ ‏ ‏بِإِهَابِهَا ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّهَا مَيْتَةٌ قَالَ إِنَّمَا حُرِّمَ أَكْلُهَا ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُصَفَّى ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ هَذَا الْحَدِيثِ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏مَا تَقُولُ فِي الثَّعَالِبِ إِذَا ‏ ‏دُبِغَتْ ‏ ‏قَالَ ‏ ‏أَكْرَهُهَا ‏","","",""],[1906,1906,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَعَبْدِ اللَّهِ ‏ ‏ابْنَيْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِمَا ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏قَالَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏مُتْعَةِ ‏ ‏النِّسَاءِ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏وَعَنْ لُحُومِ الْحُمُرِ الْإِنْسِيَّةِ ‏","","",""],[1907,1907,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَامَ رَجُلٌ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أُكِلَتْ الْحُمُرُ ‏ ‏أَوْ أُفْنِيَتْ الْحُمُرُ ‏ ‏ثُمَّ قَالَ يَا رَسُولَ اللَّهِ أُفْنِيَتْ الْحُمُرُ ‏ ‏أَوْ أُكِلَتْ الْحُمُرُ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا فَنَادَى ‏ ‏إِنَّ اللَّهَ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْ لُحُومِ الْحُمُرِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏","","",""],[1908,1908,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏أَكَلْنَا لَحْمَ فَرَسٍ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏","","",""],[1909,1909,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ وَأَذِنَ فِي لُحُومِ الْخَيْلِ ‏","","",""],[1910,1910,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَنْتَهِبُ ‏ ‏نُهْبَةً ‏ ‏ذَاتَ شَرَفٍ يَرْفَعُ الْمُؤْمِنُونَ فِيهَا أَبْصَارَهُمْ وَهُوَ حِينَ ‏ ‏يَنْتَهِبُهَا ‏ ‏مُؤْمِنٌ ‏","","",""],[1911,1911,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرِ بْنِ حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏النُّهْبَةِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَذَا فِي الْغَزْوِ إِذَا غَنِمُوا قَبْلَ أَنْ يُقْسَمَ ‏","","",""],[1912,1912,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي وَاقِدٍ ‏ ‏قَالَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ تَكُونُ بِهَا ‏ ‏الْمَخْمَصَةُ ‏ ‏فَمَا يَحِلُّ لَنَا مِنْ الْمَيْتَةِ قَالَ ‏ ‏إِذَا لَمْ تَصْطَبِحُوا وَلَمْ ‏ ‏تَغْتَبِقُوا ‏ ‏وَلَمْ ‏ ‏تَخْتَفِئُوا ‏ ‏بَقْلًا فَشَأْنُكُمْ بِهَا ‏ ‏قَالَ ‏ ‏النَّاسُ يَقُولُونَ بِالْحَاءِ وَهَذَا قَالَ بِالْخَاءِ ‏","","",""],[1913,1913,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏قَالَ ‏ ‏أَهْدَيْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقْحَةً ‏ ‏فَأَمَرَنِي أَنْ أَحْلُبَهَا فَحَلَبْتُهَا ‏ ‏فَجَهَدْتُ ‏ ‏فِي حَلْبِهَا فَقَالَ ‏ ‏دَعْ ‏ ‏دَاعِيَ اللَّبَنِ ‏","","",""],[1914,1914,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ خَالِدٍ الْقَارِظِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ قَتْلِ الضِّفْدَعِ ‏","","",""],[1915,1915,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَتْلِ أَرْبَعَةٍ مِنْ الدَّوَابِّ النَّمْلَةِ وَالنَّحْلَةِ وَالْهُدْهُدِ ‏ ‏وَالصُّرَدِ ‏","","",""],[1916,1916,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جُبَيْرِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أُمِّ شَرِيكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ ‏ ‏الْأَوْزَاغِ ‏","","",""],[1917,1917,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو زَيْدٍ سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُجَثَّمَةِ ‏ ‏وَعَنْ لَبَنِ ‏ ‏الْجَلَّالَةِ ‏ ‏وَأَنْ يُشْرَبَ مِنْ ‏ ‏فِي ‏ ‏السِّقَاءِ ‏","","",""],[1918,1918,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَيْدِ الْكَلْبِ فَقَالَ ‏ ‏مَا أَمْسَكَ عَلَيْكَ فَكُلْ فَإِنَّ أَخْذَهُ ‏ ‏ذَكَاتُهُ ‏ ‏وَإِنْ وَجَدْتَ مَعَهُ كَلْبًا فَخَشِيتَ أَنْ يَكُونَ قَدْ أَخَذَهُ مَعَهُ وَقَدْ قَتَلَهُ فَلَا تَأْكُلْهُ فَإِنَّكَ إِنَّمَا ذَكَرْتَ اسْمَ اللَّهِ عَلَى كَلْبِكَ وَلَمْ تَذْكُرْهُ عَلَى غَيْرِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَيْدِ ‏ ‏الْمِعْرَاضِ ‏ ‏فَذَكَرَ ‏ ‏مِثْلَهُ ‏","","",""],[1919,1919,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا إِلَّا كَلْبَ صَيْدٍ أَوْ مَاشِيَةٍ نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏","","",""],[1920,1920,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سُفْيَانَ بْنَ أَبِي زُهَيْرٍ ‏ ‏يُحَدِّثُ نَاسًا مَعَهُ عِنْدَ بَابِ الْمَسْجِدِ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا لَا يُغْنِي عَنْهُ زَرْعًا وَلَا ضَرْعًا نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏ ‏قَالُوا أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِي وَرَبِّ هَذَا الْمَسْجِدِ ‏","","",""],[1921,1921,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ الْكِلَابِ ثُمَّ قَالَ ‏ ‏مَا بَالِي وَلِلْكِلَابِ ثُمَّ رَخَّصَ فِي كَلْبِ الزَّرْعِ وَكَلْبِ الصَّيْدِ ‏","","",""],[1922,1922,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الْكِلَابِ ‏","","",""],[1923,1923,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنَّ الْكِلَابَ أُمَّةٌ مِنْ الْأُمَمِ لَأَمَرْتُ بِقَتْلِهَا كُلِّهَا وَلَكِنْ اقْتُلُوا مِنْهَا كُلَّ أَسْوَدَ بَهِيمٍ ‏ ‏قَالَ ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏الْبَهِيمُ الْأَسْوَدُ كُلُّهُ ‏","","",""],[1924,1924,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَدِيَّ بْنَ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمِعْرَاضِ ‏ ‏فَقَالَ ‏ ‏إِذَا أَصَابَ بِحَدِّهِ فَكُلْ وَإِذَا أَصَابَ بِعَرْضِهِ فَقَتَلَ فَإِنَّهُ ‏ ‏وَقِيذٌ ‏ ‏فَلَا تَأْكُلْ ‏","","",""],[1925,1925,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي يَعْفُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَ غَزَوَاتٍ نَأْكُلُ الْجَرَادَ ‏","","",""],[1926,1926,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏قِرَاءَةً عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ ‏ ‏مِنْ آلِ ‏ ‏الْأَزْرَقِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ أَبِي بُرْدَةَ ‏ ‏وَهُوَ رَجُلٌ مِنْ ‏ ‏بَنِي عَبْدِ الدَّارِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنْ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏","","",""],[1927,1927,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَلَاثِ مِائَةٍ فَأَصَابَنَا جُوعٌ حَتَّى أَتَيْنَا الْبَحْرَ وَقَدْ قَذَفَ دَابَّةً فَأَكَلْنَا مِنْهَا حَتَّى ‏ ‏ثَابَتْ ‏ ‏أَجْسَامُنَا فَأَخَذَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ضِلْعًا مِنْ أَضْلَاعِهَا فَوَضَعَهُ ثُمَّ حَمَلَ أَطْوَلَ رَجُلٍ فِي الْجَيْشِ عَلَى أَعْظَمِ بَعِيرٍ فِي الْجَيْشِ فَمَرَّ تَحْتَهُ ‏ ‏هَذَا مَعْنَاهُ ‏","","",""],[1928,1928,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏هِشَامُ بْنُ زَيْدِ بْنِ أَنَسٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏أَنْفَجْنَا ‏ ‏أَرْنَبًا وَنَحْنُ ‏ ‏بِمَرِّ الظَّهْرَانِ ‏ ‏فَسَعَى الْقَوْمُ ‏ ‏فَلَغِبُوا ‏ ‏فَأَخَذْتُهَا وَجِئْتُ بِهَا إِلَى ‏ ‏أَبِي طَلْحَةَ ‏ ‏فَذَبَحَهَا وَبَعَثَ بِوَرِكَيْهَا ‏ ‏أَوْ فَخِذَيْهَا شَكَّ ‏ ‏شُعْبَةُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَبِلَهَا ‏","","",""],[1929,1929,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ صَفْوَانَ ‏ ‏أَنَّهُ مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَرْنَبَيْنِ مُعَلِّقُهُمَا فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي دَخَلْتُ غَنَمَ أَهْلِي فَاصْطَدْتُ هَذَيْنِ الْأَرْنَبَيْنِ فَلَمْ أَجِدْ حَدِيدَةً ‏ ‏أُذَكِّيهِمَا ‏ ‏بِهَا ‏ ‏فَذَكَّيْتُهُمَا ‏ ‏بِمَرْوَةٍ ‏ ‏أَفَآكُلُ قَالَ نَعَمْ ‏","","",""],[1930,1930,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ فَقَالَ ‏ ‏لَسْتُ بِآكِلِهِ وَلَا مُحَرِّمِهِ ‏","","",""],[1931,1931,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ وَدِيعَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضَبٍّ فَقَالَ ‏ ‏أُمَّةٌ ‏ ‏مُسِخَتْ ‏ ‏وَاللَّهُ أَعْلَمُ ‏","","",""],[1932,1932,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو أُمَامَةَ بْنُ سَهْلِ بْنِ حُنَيْفٍ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏خَالِدَ بْنَ الْوَلِيدِ ‏ ‏الَّذِي يُقَالُ لَهُ سَيْفُ اللَّهِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ دَخَلَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ خَالَتُهُ وَخَالَةُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَوَجَدَ عِنْدَهَا ضَبًّا ‏ ‏مَحْنُوذًا ‏ ‏قَدِمَتْ بِهِ أُخْتُهَا ‏ ‏حُفَيْدَةُ بِنْتُ الْحَارِثِ ‏ ‏مِنْ ‏ ‏نَجْدٍ ‏ ‏فَقَدَّمَتْ الضَّبَّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ قَلَّ مَا يُقَدِّمُ يَدَهُ لِطَعَامٍ حَتَّى يُحَدَّثَ بِهِ وَيُسَمَّى لَهُ فَأَهْوَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ إِلَى الضَّبِّ فَقَالَتْ امْرَأَةٌ مِنْ نِسْوَةِ الْحُضُورِ أَخْبِرْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَدَّمْتُنَّ لَهُ قُلْنَ هَذَا الضَّبُّ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ فَقَالَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏أَتُحَرِّمُ الضَّبَّ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أُرَاهُ لَا وَلَكِنَّهُ لَمْ يَكُنْ بِأَرْضِ قَوْمِي فَأَجِدُنِي أَعَافُهُ قَالَ ‏ ‏خَالِدٌ ‏ ‏فَاجْتَرَرْتُهُ فَأَكَلْتُهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُ فَلَمْ يَنْهَنِي ‏","","",""],[1933,1933,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَحْسَبُهُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي وَاقِدٍ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَالنَّاسُ ‏ ‏يَجُبُّونَ ‏ ‏أَسْنِمَةَ الْإِبِلِ وَأَلْيَاتِ الْغَنَمِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُطِعَ مِنْ بَهِيمَةٍ وَهِيَ حَيَّةٌ فَهُوَ مَيْتَةٌ ‏","","",""],[1934,1934,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏سَمِّ اللَّهَ وَكُلْ مِمَّا يَلِيكَ ‏","","",""],[1935,1935,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْكُلُ طَعَامًا فِي سِتَّةِ نَفَرٍ مِنْ أَصْحَابِهِ فَجَاءَ أَعْرَابِيٌّ فَأَكَلَهُ بِلُقْمَتَيْنِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنَّهُ ‏ ‏لَوْ ذَكَرَ اسْمَ اللَّهِ لَكَفَاكُمْ فَإِذَا أَكَلَ أَحَدُكُمْ فَلْيَذْكُرْ اسْمَ اللَّهِ فَإِنْ نَسِيَ أَنْ يَذْكُرَ اسْمَ اللَّهِ فَلْيَقُلْ بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ ‏ ‏أَخْبَرَنَا ‏ ‏بُنْدَارٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِهَذَا الْحَدِيثِ ‏","","",""],[1936,1936,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بُسْرٍ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ يَسِيرَةٌ ‏ ‏قَالَ ‏ ‏قَالَ أَبِي لِأُمِّي لَوْ صَنَعْتِ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامًا فَصَنَعَتْ ‏ ‏ثَرِيدَةً ‏ ‏وَقَالَ بِيَدِهِ ‏ ‏يُقْلِلُ ‏ ‏فَانْطَلَقَ أَبِي فَدَعَاهُ فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ عَلَى ‏ ‏ذِرْوَتِهَا ‏ ‏ثُمَّ قَالَ ‏ ‏خُذُوا بِاسْمِ اللَّهِ فَأَخَذُوا مِنْ نَوَاحِيهَا فَلَمَّا طَعِمُوا دَعَا لَهُمْ فَقَالَ اللَّهُمَّ اغْفِرْ لَهُمْ وَارْحَمْهُمْ وَبَارِكْ لَهُمْ فِي رِزْقِهِمْ ‏","","",""],[1937,1937,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْقَاسِمِ الْأَسَدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَكَلَ أَوْ شَرِبَ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ مَكْفُورٍ ‏ ‏وَلَا مُوَدَّعٍ ‏ ‏وَلَا مُسْتَغْنًى عَنْ رَبِّنَا ‏","","",""],[1938,1938,"","","‏ ‏أَخْبَرَنَا ‏ ‏نُعَيْمُ بْنُ حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ سَنَّةَ ‏ ‏عَنْ أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطَّاعِمُ الشَّاكِرُ كَالصَّائِمِ الصَّابِرِ ‏","","",""],[1939,1939,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَلْعَقْ أَصَابِعَهُ الثَّلَاثَ ‏","","",""],[1940,1940,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلَا يَمْسَحْ يَدَهُ حَتَّى يَلْعَقَ أَصَابِعَهُ أَوْ يُلْعِقَهَا ‏","","",""],[1941,1941,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْيَمَانِ الْبَرَّاءُ هُوَ مُعَلَّى بْنُ رَاشِدٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏أُمُّ عَاصِمٍ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيْنَا ‏ ‏نُبَيْشَةُ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَأْكُلُ طَعَامًا فَدَعَوْنَاهُ فَأَكَلَ مَعَنَا ‏ ‏ثُمَّ قَالَ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏مَنْ أَكَلَ فِي قَصْعَةٍ ثُمَّ لَحِسَهَا اسْتَغْفَرَتْ لَهُ ‏ ‏الْقَصْعَةُ ‏","","",""],[1942,1942,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَقَطَتْ لُقْمَةُ أَحَدِكُمْ فَلْيَمْسَحْ عَنْهَا التُّرَابَ وَلْيُسَمِّ اللَّهَ وَلْيَأْكُلْهَا ‏","","",""],[1943,1943,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَعْقِلُ بْنُ يَسَارٍ ‏ ‏يَتَغَدَّى فَسَقَطَتْ لُقْمَتُهُ فَأَخَذَهَا ‏ ‏فَأَمَاطَ ‏ ‏مَا بِهَا مِنْ أَذًى ثُمَّ أَكَلَهَا فَجَعَلَ أُولَئِكَ ‏ ‏الدَّهَاقِينُ ‏ ‏يَتَغَامَزُونَ ‏ ‏بِهِ فَقَالُوا لَهُ مَا ‏ ‏تَرَى مَا يَقُولُ هَؤُلَاءِ الْأَعَاجِمُ يَقُولُونَ انْظُرُوا إِلَى مَا بَيْنَ يَدَيْهِ مِنْ الطَّعَامِ وَإِلَى مَا يَصْنَعُ بِهَذِهِ اللُّقْمَةِ فَقَالَ إِنِّي لَمْ أَكُنْ أَدَعُ مَا سَمِعْتُ بِقَوْلِ هَؤُلَاءِ الْأَعَاجِمِ إِنَّا كُنَّا نُؤْمَرُ ‏ ‏إِذَا سَقَطَتْ مِنْ أَحَدِنَا لُقْمَةٌ أَنْ ‏ ‏يُمِيطَ ‏ ‏مَا بِهَا مِنْ الْأَذَى وَأَنْ يَأْكُلَهَا ‏","","",""],[1944,1944,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُحَمَّدٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَأْكُلْ بِيَمِينِهِ وَلْيَشْرَبْ بِيَمِينِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ ‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏","","",""],[1945,1945,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنِي ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏أَبْصَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُسْرَ بْنَ رَاعِي الْعِيرِ ‏ ‏يَأْكُلُ بِشِمَالِهِ فَقَالَ ‏ ‏كُلْ بِيَمِينِكَ قَالَ لَا أَسْتَطِيعُ قَالَ لَا اسْتَطَعْتَ قَالَ فَمَا وَصَلَتْ يَمِينُهُ إِلَى ‏ ‏فِيهِ ‏","","",""],[1946,1946,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ الْمَدَنِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ بِثَلَاثِ أَصَابِعَ وَلَا يَمْسَحُ يَدَهُ حَتَّى يَلْعَقَهَا ‏","","",""],[1947,1947,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ الْمَدَنِيِّ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبٍ ‏ ‏أَوْ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ كَعْبٍ ‏ ‏شَكَّ ‏ ‏هِشَامٌ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْكُلُ بِأَصَابِعِهِ الثَّلَاثِ فَإِذَا فَرَغَ لَعِقَهَا وَأَشَارَ ‏ ‏هِشَامٌ ‏ ‏بِأَصَابِعِهِ الثَّلَاثِ ‏","","",""],[1948,1948,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ جَائِزَتَهُ يَوْمًا وَلَيْلَةً وَالضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ وَمَا بَعْدَ ذَلِكَ صَدَقَةٌ ‏","","",""],[1949,1949,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏سَمِعَ ‏ ‏نَافِعَ بْنَ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْخُزَاعِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُحْسِنْ إِلَى جَارِهِ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ ‏","","",""],[1950,1950,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْجُودِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ أَبِي كَرِيمَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا مُسْلِمٍ ضَافَ قَوْمًا فَأَصْبَحَ الضَّيْفُ مَحْرُومًا فَإِنَّ عَلَى كُلِّ مُسْلِمٍ نَصْرَهُ حَتَّى يَأْخُذَ لَهُ ‏ ‏بِقِرَى ‏ ‏لَيْلَتِهِ مِنْ زَرْعِهِ وَمَالِهِ ‏","","",""],[1951,1951,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عُتْبَةَ بْنِ مُسْلِمٍ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ بْنَ حُنَيْنٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَقَطَ الذُّبَابُ فِي شَرَابِ أَحَدِكُمْ فَلْيَغْمِسْهُ كُلَّهُ ثُمَّ لِيَنْزِعْهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً وَفِي الْآخَرِ شِفَاءً ‏","","",""],[1952,1952,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْمِسْهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً وَفِي الْآخَرِ شِفَاءً ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏قَالَ ‏ ‏غَيْرُ ‏ ‏حَمَّادٍ ‏ ‏ثُمَامَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏مَكَانَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَقَوْمٌ ‏ ‏يَقُولُونَ عَنْ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَحَدِيثُ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏أَصَحُّ ‏","","",""],[1953,1953,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1954,1954,"","","‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[1955,1955,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامُ الْوَاحِدِ يَكْفِي ‏ ‏الِاثْنَيْنِ وَطَعَامُ ‏ ‏الِاثْنَيْنِ يَكْفِي الْأَرْبَعَةَ وَطَعَامُ الْأَرْبَعَةِ يَكْفِي ثَمَانِيَةً ‏","","",""],[1956,1956,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏سَمِّ اللَّهَ وَكُلْ مِمَّا يَلِيكَ ‏","","",""],[1957,1957,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِجَفْنَةٍ ‏ ‏أَوْ قَالَ ‏ ‏قَصْعَةٍ ‏ ‏مِنْ ‏ ‏ثَرِيدٍ ‏ ‏فَقَالَ ‏ ‏كُلُوا مِنْ حَافَاتِهَا ‏ ‏أَوْ قَالَ جَوَانِبِهَا ‏ ‏وَلَا تَأْكُلُوا مِنْ وَسَطِهَا فَإِنَّ الْبَرَكَةَ تَنْزِلُ فِي وَسَطِهَا ‏","","",""],[1958,1958,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏قُرَّةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا كَانَتْ إِذَا أُتِيَتْ ‏ ‏بِثَرِيدٍ ‏ ‏أَمَرَتْ بِهِ فَغُطِّيَ حَتَّى يَذْهَبَ فَوْرَةُ دُخَانِهِ وَتَقُولُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏هُوَ أَعْظَمُ لِلْبَرَكَةِ ‏","","",""],[1959,1959,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُثَنَّى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ نَافِعٍ أَبُو سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي ذَاتَ يَوْمٍ إِلَى مَنْزِلِهِ فَقَالَ ‏ ‏هَلْ مِنْ غَدَاءٍ ‏ ‏أَوْ مِنْ عَشَاءٍ شَكَّ ‏ ‏طَلْحَةُ ‏ ‏قَالَ فَأَخْرَجَ إِلَيْهِ ‏ ‏فِلَقًا ‏ ‏مِنْ خُبْزٍ فَقَالَ أَمَا مِنْ ‏ ‏أُدْمٍ ‏ ‏قَالُوا لَا إِلَّا شَيْءٌ مِنْ خَلٍّ فَقَالَ هَاتُوهُ فَنِعْمَ ‏ ‏الْإِدَامُ ‏ ‏الْخَلُّ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَمَا زِلْتُ أُحِبُّ الْخَلَّ مُنْذُ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَمَا زِلْتُ أُحِبُّهُ مُنْذُ سَمِعْتُهُ مِنْ ‏ ‏جَابِرٍ ‏","","",""],[1960,1960,"","","‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نِعْمَ ‏ ‏الْإِدَامُ ‏ ‏أَوْ نِعْمَ ‏ ‏الْأُدْمُ ‏ ‏الْخَلُّ ‏","","",""],[1961,1961,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِمَرَقَةٍ فِيهَا ‏ ‏دُبَّاءٌ ‏ ‏وَقَدِيدٌ ‏ ‏فَرَأَيْتُهُ ‏ ‏يَتَتَبَّعُ ‏ ‏الدُّبَّاءَ ‏ ‏يَأْكُلُهُ ‏","","",""],[1962,1962,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ الْقَرْعُ قَالَ فَقُدِّمَ إِلَيْهِ فَجَعَلْتُ أَتَنَاوَلُهُ وَأَجْعَلُهُ بَيْنَ يَدَيْهِ ‏","","",""],[1963,1963,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَلَيْسَ ‏ ‏بِابْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي أَسِيدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُوا الزَّيْتَ ‏ ‏وَائْتَدِمُوا ‏ ‏بِهِ وَادَّهِنُوا بِهِ فَإِنَّهُ يَخْرُجُ مِنْ شَجَرَةٍ مُبَارَكَةٍ ‏","","",""],[1964,1964,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي غَزْوَةِ ‏ ‏خَيْبَرَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ ‏ ‏يَعْنِي الثُّومَ ‏ ‏فَلَا يَأْتِيَنَّ الْمَسَاجِدَ ‏","","",""],[1965,1965,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أُمَّ أَيُّوبَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏نَزَلَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَكَلَّفْنَا لَهُ طَعَامًا فِيهِ شَيْءٌ مِنْ بَعْضِ هَذِهِ الْبُقُولِ فَلَمَّا أَتَيْنَاهُ بِهِ كَرِهَهُ وَقَالَ لِأَصْحَابِهِ كُلُوهُ ‏ ‏فَإِنِّي لَسْتُ كَأَحَدٍ مِنْكُمْ إِنِّي أَخَافُ أَنْ أُوذِيَ صَاحِبِي ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏إِذَا لَمْ يُؤْذِ أَحَدًا فَلَا بَأْسَ بِأَكْلِهِ ‏","","",""],[1966,1966,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَبِي مُوسَى ‏ ‏فَقُدِّمَ طَعَامُهُ ‏ ‏فَقُدِّمَ فِي طَعَامِهِ لَحْمُ دَجَاجٍ وَفِي الْقَوْمِ رَجُلٌ مِنْ ‏ ‏بَنِي تَيْمِ اللَّهِ ‏ ‏أَحْمَرُ فَلَمْ يَدْنُ ‏ ‏فَقَالَ لَهُ ‏ ‏أَبُو مُوسَى ‏ ‏ادْنُ فَإِنِّي قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ مِنْهُ ‏","","",""],[1967,1967,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُ ‏ ‏ذَكَرَ الدَّجَاجَ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُهُ ‏","","",""],[1968,1968,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ غَيْلَانَ ‏ ‏أَنَّ ‏ ‏الْوَلِيدَ بْنَ قَيْسٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَصْحَبْ إِلَّا مُؤْمِنًا وَلَا يَأْكُلْ طَعَامَكَ إِلَّا تَقِيٌّ ‏","","",""],[1969,1969,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ ‏ ‏الْقِثَّاءَ ‏ ‏بِالرُّطَبِ ‏","","",""],[1970,1970,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏جَبَلَةُ بْنُ سُحَيْمٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏بِالْمَدِينَةِ ‏ ‏فَأَصَابَتْنَا سَنَةٌ فَكَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُ التَّمْرَ وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَمُرُّ بِنَا وَيَقُولُ لَا ‏ ‏تُقَارِنُوا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْقِرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ ‏","","",""],[1971,1971,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ مُحَمَّدِ بْنِ طَحْلَاءَ ‏ ‏عَنْ ‏ ‏أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏بَيْتٌ لَا تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ ‏ ‏أَوْ جَاعَ أَهْلُهُ ‏ ‏مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏","","",""],[1972,1972,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجُوعُ أَهْلُ بَيْتٍ عِنْدَهُمْ التَّمْرُ ‏","","",""],[1973,1973,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏أُهْدِيَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمْرٌ فَأَخَذَ ‏ ‏يُهَدِّيهِ وَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ تَمْرًا مُقْعِيًا مِنْ الْجُوعِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يُهَدِّيهِ ‏ ‏يَعْنِي يُهْدِي هَاهُنَا وَهَاهُنَا ‏","","",""],[1974,1974,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَامَ وَفِي يَدِهِ رِيحُ ‏ ‏غَمَرٍ ‏ ‏فَعَرَضَ لَهُ عَارِضٌ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ ‏","","",""],[1975,1975,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏وَرَأَى عَلَيْهِ ‏ ‏وَضَرًا ‏ ‏مِنْ صُفْرَةٍ مَهْيَمْ ‏ ‏قَالَ تَزَوَّجْتُ قَالَ ‏ ‏أَوْلِمْ وَلَوْ بِشَاةٍ ‏","","",""],[1976,1976,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏ثَقِيفَ ‏ ‏أَعْوَرَ قَالَ كَانَ يُقَالُ لَهُ مَعْرُوفٌ أَيْ ‏ ‏يُثْنَى عَلَيْهِ خَيْرٌ إِنْ لَمْ يَكُنْ اسْمُهُ ‏ ‏زُهَيْرَ بْنَ عُثْمَانَ ‏ ‏فَلَا أَدْرِي مَا اسْمُهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلِيمَةُ أَوَّلَ يَوْمٍ حَقٌّ وَالثَّانِيَ مَعْرُوفٌ وَالثَّالِثَ سُمْعَةٌ وَرِيَاءٌ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ دُعِيَ أَوَّلَ يَوْمٍ فَأَجَابَ وَدُعِيَ الْيَوْمَ الثَّانِيَ فَأَجَابَ وَدُعِيَ الْيَوْمَ الثَّالِثَ ‏ ‏فَحَصَبَ ‏ ‏الرَّسُولَ وَلَمْ يُجِبْهُ وَقَالَ أَهْلُ سُمْعَةٍ وَرِيَاءٍ ‏","","",""],[1977,1977,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏شَرُّ الطَّعَامِ طَعَامُ الْوَلِيمَةِ يُدْعَى إِلَيْهَا الْأَغْنِيَاءُ وَيُتْرَكُ الْمَسَاكِينُ وَمَنْ تَرَكَ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[1978,1978,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ قَدْ صَنَعَ طَعَامًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي فَدَعَاهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَكَذَا ‏ ‏وَأَوْمَأَ ‏ ‏إِلَيْهِ بِيَدِهِ قَالَ يَقُولُ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَكَذَا وَأَشَارَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏قَالَ لَا فَأَعْرَضَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ الثَّانِيَةَ ‏ ‏وَأَوْمَأَ ‏ ‏إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْرَضَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْمَأَ إِلَيْهِ الثَّالِثَةَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذِهِ قَالَ نَعَمْ فَانْطَلَقَ مَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَائِشَةُ ‏ ‏فَأَكَلَا مِنْ طَعَامِهِ ‏","","",""],[1979,1979,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ يُقَالُ لَهُ ‏ ‏أَبُو شُعَيْبٍ ‏ ‏وَكَانَ لَهُ غُلَامٌ لَحَّامٌ فَقَالَ اصْنَعْ لِي طَعَامًا أَدْعُو رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَامِسَ خَمْسَةٍ قَالَ فَدَعَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَامِسَ خَمْسَةٍ فَتَبِعَهُمْ رَجُلٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ دَعَوْتَنَا خَامِسَ خَمْسَةٍ وَهَذَا رَجُلٌ قَدْ تَبِعَنِي فَإِنْ شِئْتَ أَذِنْتَ لَهُ وَإِنْ شِئْتَ تَرَكْتَهُ قَالَ فَأَذِنَ لَهُ ‏","","",""],[1980,1980,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي طُوَالَةَ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضْلُ ‏ ‏عَائِشَةَ ‏ ‏عَلَى النِّسَاءِ كَفَضْلِ ‏ ‏الثَّرِيدِ ‏ ‏عَلَى سَائِرِ الطَّعَامِ ‏","","",""],[1981,1981,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمَدِينِيِّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْكَرِيمِ أَبُو أُمَيَّةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏زَوَّجَنِي أَبِي فِي إِمَارَةِ ‏ ‏عُثْمَانَ ‏ ‏فَدَعَا ‏ ‏رَهْطًا ‏ ‏مِنْ أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ فِيمَنْ دَعَا ‏ ‏صَفْوَانُ بْنُ أُمَيَّةَ ‏ ‏وَهُوَ شَيْخٌ كَبِيرٌ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏انْهَسُوا ‏ ‏اللَّحْمَ ‏ ‏نَهْسًا ‏ ‏فَإِنَّهُ أَشْهَى وَأَمْرَأُ ‏","","",""],[1982,1982,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْأَقْمَرِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو جُحَيْفَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا آكُلُ مُتَّكِئًا ‏","","",""],[1983,1983,"","","‏ ‏أَخْبَرَنَا ‏ ‏نُعَيْمُ بْنُ حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِالْبَاكُورَةِ بِأَوَّلِ الثَّمَرَةِ قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏مَدِينَتِنَا ‏ ‏وَفِي ثَمَرَتِنَا وَفِي ‏ ‏مُدِّنَا ‏ ‏وَفِي ‏ ‏صَاعِنَا ‏ ‏بَرَكَةً مَعَ بَرَكَةٍ ثُمَّ يُعْطِيهِ أَصْغَرَ مَنْ يَحْضُرُهُ مِنْ الْوِلْدَانِ ‏","","",""],[1984,1984,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِالطَّعَامِ فَلْيُجْلِسْهُ فَإِنْ أَبَى فَلْيُنَاوِلْهُ ‏","","",""],[1985,1985,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَى أَحَدَكُمْ خَادِمُهُ بِطَعَامِهِ فَلْيُجْلِسْهُ مَعَهُ وَلْيُنَاوِلْهُ لُقْمَةً أَوْ لُقْمَتَيْنِ أَوْ أُكْلَةً أَوْ أُكْلَتَيْنِ فَإِنَّهُ ‏ ‏وَلِيَ ‏ ‏حَرَّهُ ‏ ‏وَدُخَانَهُ ‏","","",""],[1986,1986,"","","‏ ‏حَدَّثَنَا ‏ ‏فَرْوَةُ بْنُ أَبِي الْمَغْرَاءِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ الْحَلْوَاءَ وَالْعَسَلَ ‏","","",""],[1987,1987,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْبِرَازِ فَقُدِّمَ إِلَيْهِ طَعَامٌ فَقِيلَ لَهُ أَلَا تَوَضَّأُ قَالَ فَقَالَ ‏ ‏أُصَلِّي فَأَتَوَضَّأُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏إِنَّمَا هُوَ ‏ ‏سَعِيدُ بْنُ الْحُوَيْرِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَسَمِعْتُ ‏ ‏أَبَا عَاصِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِإِسْنَادِهِ ‏","","",""],[1988,1988,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَجْنَبَ فَأَرَادَ أَنْ يَأْكُلَ أَوْ يَنَامَ تَوَضَّأَ ‏","","",""],[1989,1989,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏أَوْصَانِي خَلِيلِي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِذَا طَبَخْتَ مَرَقَةً فَأَكْثِرْ مَاءَهَا ثُمَّ انْظُرْ أَهْلَ بَيْتٍ مِنْ جِيرَتِكَ فَاغْرِفْ لَهُمْ مِنْهَا ‏","","",""],[1990,1990,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وُضِعَ الطَّعَامُ فَاخْلَعُوا نِعَالَكُمْ فَإِنَّهُ أَرْوَحُ لِأَقْدَامِكُمْ ‏","","",""],[1991,1991,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْبُدُوا الرَّحْمَنَ وَأَفْشُوا السَّلَامَ وَأَطْعِمُوا الطَّعَامَ تَدْخُلُوا الْجِنَانَ ‏","","",""],[1992,1992,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَجِيبُوا الدَّاعِيَ إِذَا دُعِيتُمْ قَالَ وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَأْتِي الدَّعْوَةَ فِي الْعُرْسِ وَفِي غَيْرِ الْعُرْسِ وَيَأْتِيهَا وَهُوَ صَائِمٌ ‏","","",""],[1993,1993,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ فَأْرَةٍ وَقَعَتْ فِي سَمْنٍ فَقَالَ ‏ ‏أَلْقُوهَا وَمَا حَوْلَهَا وَكُلُوا ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏بِإِسْنَادِهِ ‏","","",""],[1994,1994,"","","‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ فَأْرَةٍ وَقَعَتْ فِي سَمْنٍ فَمَاتَتْ فَقَالَ ‏ ‏خُذُوهَا وَمَا حَوْلَهَا فَاطْرَحُوهُ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏إِذَا كَانَ ذَائِبًا ‏ ‏أُهَرِيقَ ‏","","",""],[1995,1995,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ الْحِمْيَرِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَعْدٍ الْخَيْرُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ فَلْيَتَخَلَّلْ فَمَا تَخَلَّلَ فَلْيَلْفِظْهُ وَمَا لَاكَ بِلِسَانِهِ فَلْيَبْتَلِعْ ‏","","",""],[1996,1996,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ أُسْرِيَ بِهِ ‏ ‏بِإِيلِيَاءَ ‏ ‏بِقَدَحَيْنِ مِنْ خَمْرٍ وَلَبَنٍ فَنَظَرَ إِلَيْهِمَا ثُمَّ أَخَذَ اللَّبَنَ فَقَالَ ‏ ‏جِبْرِيلُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي هَدَاكَ لِلْفِطْرَةِ لَوْ أَخَذْتَ الْخَمْرَ ‏ ‏غَوَتْ ‏ ‏أُمَّتُكَ ‏","","",""],[1997,1997,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ سَاقِيَ الْقَوْمِ فِي مَنْزِلِ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ فَنَزَلَ تَحْرِيمُ الْخَمْرِ قَالَ ‏ ‏فَأَمَرَ ‏ ‏مُنَادِيًا فَنَادَى فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏اخْرُجْ فَانْظُرْ مَا هَذَا فَخَرَجْتُ فَقُلْتُ هَذَا مُنَادٍ يُنَادِي ‏ ‏أَلَا إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ فَقَالَ ‏ ‏لِيَ اذْهَبْ ‏ ‏فَأَهْرِقْهَا ‏ ‏قَالَ فَجَرَتْ فِي سِكَكِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ وَكَانَتْ خَمْرُهُمْ يَوْمَئِذٍ ‏ ‏الْفَضِيخَ ‏ ‏فَقَالَ بَعْضُ الْقَوْمِ قُتِلَ قَوْمٌ وَهِيَ فِي بُطُونِهِمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ ‏ ‏جُنَاحٌ ‏ ‏فِيمَا طَعِمُوا إِذَا مَا اتَّقَوْا وَآمَنُوا ‏} ‏الْآيَةَ ‏","","",""],[1998,1998,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا ثُمَّ لَمْ يَتُبْ مِنْهَا حُرِمَهَا فِي الْآخِرَةِ فَلَمْ يُسْقَهَا ‏","","",""],[1999,1999,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏لَهُ ‏ ‏بِالطَّائِفِ ‏ ‏يُقَالُ لَهُ الْوَهْطُ فَإِذَا هُوَ ‏ ‏مُخَاصِرٌ ‏ ‏فَتًى مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُزَنُّ ‏ ‏ذَلِكَ الْفَتَى بِشُرْبِ الْخَمْرِ فَقُلْتُ خِصَالٌ بَلَغَتْنِي عَنْكَ أَنَّكَ تُحَدِّثُ بِهَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ مَنْ شَرِبَ الْخَمْرَ شَرْبَةً لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ صَبَاحًا فَلَمَّا أَنْ سَمِعَهُ الْفَتَى يَذْكُرُ الْخَمْرَ ‏ ‏اخْتَلَجَ ‏ ‏يَدَهُ مِنْ يَدِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏ثُمَّ وَلَّى فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏اللَّهُمَّ إِنِّي لَا أُحِلُّ لِأَحَدٍ أَنْ يَقُولَ عَلَيَّ مَا لَمْ أَقُلْ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ شَرِبَ الْخَمْرَ شَرْبَةً لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ صَبَاحًا فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ ‏ ‏فَلَا أَدْرِي فِي الثَّالِثَةِ أَمْ فِي الرَّابِعَةِ ‏ ‏كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ ‏ ‏رَدْغَةِ ‏ ‏الْخَبَالِ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[2000,2000,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ أَبِي جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَقْعُدْ عَلَى مَائِدَةٍ يُشْرَبُ عَلَيْهَا الْخَمْرُ ‏","","",""]];
